import { readFileSync } from "node:fs";
import { join } from "node:path";
import { log } from "./log";
import type { WindowManager } from "../windows/WindowManager";

/**
 * Dictation feedback chimes — start and cancel. The WAVs are generated by
 * scripts/gen-sounds.cjs (two soft two-tone chimes, no licensed assets) and
 * shipped next to the other resources.
 *
 * Playback happens in the overlay renderer (main can't play audio); main reads
 * the file and hands over a data URL so the renderer needs no filesystem
 * access of its own. If no overlay window exists (rest bar off, mid-cleanup),
 * the chime is skipped — never created for its own sake.
 */
const cache = new Map<string, string>();

/** Reads a sound as a data URL (memoized — the files are ~20 KB). */
function soundDataUrl(name: string): string | null {
  const cached = cache.get(name);
  if (cached) return cached;
  try {
    const file = join(__dirname, "../../resources/sounds", `${name}.wav`);
    const buf = readFileSync(file);
    const url = `data:audio/wav;base64,${buf.toString("base64")}`;
    cache.set(name, url);
    return url;
  } catch (err) {
    log(`sound: ${name}.wav unavailable — ${String(err).slice(0, 90)}`);
    return null;
  }
}

/** Plays a chime in the overlay renderer, if that window is alive. */
export function playSound(windows: WindowManager, name: "start" | "cancel"): void {
  const dataUrl = soundDataUrl(name);
  if (!dataUrl) return;
  windows.sendToOverlay("sound/play", { name, dataUrl });
}
